V13.pmiCalc=function(){var h=N($('v13PmiHome').value),down=N($('v13PmiDown').value),rate=N($('v13PmiRate').value),term=N($('v13PmiTerm').value)||30,int=N($('v13PmiInterest').value)/100,loan=h*(1-down/100),monthly=loan*rate/100/12,r=int/12,pay=r?loan*r*Math.pow(1+r,term*12)/(Math.pow(1+r,term*12)-1):loan/(term*12),bal=loan,m=0;while(h&&bal/h>.8&&m<term*12){bal=bal*(1+r)-pay;m++;}var total=monthly*m;$('v13PmiResults').innerHTML='<div class="v13-kpis"><div class="v13-kpi"><span>Current LTV</span><b>'+(h?loan/h*100:0).toFixed(2)+'%</b></div><div class="v13-kpi"><span>Annual PMI estimate</span><b>'+rate.toFixed(3)+'%</b></div><div class="v13-kpi"><span>Monthly PMI</span><b>'+usd(monthly)+'</b></div><div class="v13-kpi"><span>Estimated total</span><b>'+usd(total)+'</b></div></div><div class="note"><div>Estimated 80% LTV timing: month '+m+' ('+(m/12).toFixed(1)+' years), assuming scheduled payments and no value change. Automatic termination may follow different rules. Obtain an insurer quote and servicer guidance.</div></div>';};
