var V=window.V15={version:'15.0',plSource:'',compareSelected:{},_adjusted:new WeakSet()};

/* Every date can be typed. A tolerant parser normalizes valid values on blur. */
V.parseDate=function(raw){
  if(window.V7&&V7.parseDate){var x=V7.parseDate(raw);if(x)return x;}
  var s=String(raw||'').trim(),m,now=new Date(),y,mo,d;
  if(!s)return '';
  if(/^(today|t)$/i.test(s)){return [now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');}
  if((m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/))){y=+m[1];mo=+m[2];d=+m[3];}
  else if((m=s.match(/^(\d{1,2})[-/. ](\d{1,2})(?:[-/. ](\d{2,4}))?$/))){mo=+m[1];d=+m[2];y=m[3]?+m[3]:now.getFullYear();if(y<100)y+=2000;}
  else if(/jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec/i.test(s)){var t=Date.parse(/\d{4}/.test(s)?s:s+' '+now.getFullYear());if(!isNaN(t)){var q=new Date(t);y=q.getFullYear();mo=q.getMonth()+1;d=q.getDate();}}
  if(!y)return '';
  var dt=new Date(y,mo-1,d);if(dt.getFullYear()!==y||dt.getMonth()!==mo-1||dt.getDate()!==d)return '';
  return y+'-'+String(mo).padStart(2,'0')+'-'+String(d).padStart(2,'0');
};
V.prettyDate=function(v){var x=V.parseDate(v),m=x.match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?m[2]+'/'+m[3]+'/'+m[1]:v;};
V.defaultPlDates=function(){var now=new Date(),end=new Date(now.getFullYear(),now.getMonth(),0);return{start:now.getFullYear()+'-01-01',end:end.getFullYear()+'-'+String(end.getMonth()+1).padStart(2,'0')+'-'+String(end.getDate()).padStart(2,'0'),prepared:now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0')};};
function enhanceDateInput(el){
  if(el.__v15date||el.classList.contains('dpick'))return;
  var inline=el.getAttribute('onchange')||'',handler=el.onchange,key=el.getAttribute('data-v15-key');
  if(el.type!=='date'&&!key)return;
  el.__v15date=true;el.dataset.v15Iso=V.parseDate(el.value)||'';el.type='text';el.placeholder='MM/DD/YYYY';el.autocomplete='off';el.value=V.prettyDate(el.dataset.v15Iso);
  el.removeAttribute('onchange');el.onchange=null;
  el.addEventListener('blur',function(){var iso=V.parseDate(el.value);if(!iso&&el.value.trim()){el.classList.add('v15-date-bad');setTimeout(function(){el.classList.remove('v15-date-bad');el.value=V.prettyDate(el.dataset.v15Iso);},850);return;}el.dataset.v15Iso=iso;el.value=V.prettyDate(iso);if(key&&window.V13&&V13.PL){V13.PL[key]=iso;V14.renderPL();return;}var old=el.value;el.value=iso;try{if(handler)handler.call(el,new Event('change',{bubbles:false}));else if(inline)Function(inline).call(el);}catch(e){}el.value=V.prettyDate(iso);});
  el.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();el.blur();}if(e.key==='Escape'){el.value=V.prettyDate(el.dataset.v15Iso);el.blur();}});
}
function enhanceDates(){
  $$('input[type="date"]').forEach(enhanceDateInput);
  $$('.datefld .dtxt').forEach(function(el){if(el.__v15loose)return;el.__v15loose=true;el.placeholder='MM/DD/YYYY or typed date';});
}

/* Print exactly one generated document, never the application chrome. */
V.printNode=function(id,title){var node=$(id);if(!node)return;var w=window.open('','_blank');if(!w)return say('Pop-up blocked','Allow pop-ups to print this document.','warn');var css=$$('style').map(function(s){return s.textContent;}).join('\n');w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+esc(title||'Document')+'</title><style>'+css+' body{background:#fff;margin:0}.no-print{display:none!important}</style></head><body>'+node.outerHTML+'</body></html>');w.document.close();setTimeout(function(){w.focus();w.print();},450);};

/* Professional P&L with source pull, fixed YTD dates, and detailed analysis. */
function plTotals(){var P=V13.PL,inc=P.income.reduce(function(a,x){return a+N(x.amount);},0),exp=P.expenses.reduce(function(a,x){return a+N(x.amount);},0);return{inc:inc,exp:exp,net:inc-exp,margin:inc?(inc-exp)/inc*100:0,ratio:inc?exp/inc*100:0};}
function plMonths(){var P=V13.PL,a=V.parseDate(P.start),b=V.parseDate(P.end);if(!a||!b)return 12;var days=(new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000+1;return Math.max(1,days/30.4375);}
function plSourceOptions(){var S=calcState(),out=['<option value="">Choose Schedule C or entity</option>'];(S&&S.schc||[]).forEach(function(x){out.push('<option value="schc:'+esc(x.id)+'"'+(V.plSource==='schc:'+x.id?' selected':'')+'>Schedule C - '+esc(x.name||'Unnamed business')+'</option>');});(S&&S.corp||[]).forEach(function(x){out.push('<option value="corp:'+esc(x.id)+'"'+(V.plSource==='corp:'+x.id?' selected':'')+'>'+esc(x.form||'Entity')+' - '+esc(x.name||'Unnamed entity')+'</option>');});return out.join('');}
V.pullPL=function(){var S=calcState(),P=V13.PL,parts=String(V.plSource||'').split(':'),list=S&&S[parts[0]],rec=list&&list.filter(function(x){return String(x.id)===parts[1];})[0];if(!rec)return say('Choose a business','Select a Schedule C or business entity first.','warn');var r=parts[0]==='schc'&&window.calcSchC?calcSchC(rec):(window.calcCorp?calcCorp(rec):null);P.business=rec.name||P.business;P.owner=(S.b1||S.borrower||P.owner);P.sourceLabel=(parts[0]==='schc'?'Schedule C':rec.form||'Business entity')+' - '+(rec.name||'business');P.sourceMonthly=r?N(r.monthly):0;P.sourceAnnual=r?N(r.a1):0;if(P.income.length&&P.income.every(function(x){return !N(x.amount);})&&r){P.income[0].name=parts[0]==='schc'?'Most recent Schedule C adjusted income':'Most recent entity adjusted income';P.income[0].amount=N(r.a1);}V14.renderPL();say('Business source linked','Existing self-employment values were copied; no missing revenue or expense was invented.');};
V.goSelfEmployment=function(){if(window.V14)V14.close('v13PlModal');if(window.switchTab)switchTab('selfemp');};
V.setPlRoot=function(k,v){var P=V13.PL;P[k]=(k==='priorIncome'||k==='priorExpenses'||k==='cushionPct')?N(v):v;V14.renderPL();};
function enhancePL(){
  if(!window.V13||!V13.PL||!window.V14||!V14.renderPL)return false;
  var P=V13.PL,defs=V.defaultPlDates();if(!P.__v15dates){P.__v15dates=true;P.start=defs.start;P.end=defs.end;if(!P.prepared)P.prepared=defs.prepared;}if(P.cushionPct==null)P.cushionPct=10;
  if(!V14.renderPL.__v15){var old=V14.renderPL;var wrapped=function(){old();var body=$('v13PlBody');if(!body)return;var input=body.querySelector('.v14-doc-inputs'),doc=body.querySelector('.v14-doc');if(!input||!doc)return;doc.id='v15PlStatement';
      var bar=input.querySelector('.v14-bar');if(bar&&!$('v15PlActions')){var a=document.createElement('span');a.id='v15PlActions';a.className='v14-bar';a.innerHTML='<button class="btn btn-light btn-sm" onclick="V15.goSelfEmployment()">Open Self-Employment</button><button class="btn btn-primary btn-sm v15-pl-print-only" onclick="V15.printNode(\'v15PlStatement\',\'Profit and Loss Statement\')">Print statement only</button>';bar.appendChild(a);}
      var source=document.createElement('div');source.className='v15-pl-source no-print';source.innerHTML='<div class="field"><label>Pull business source</label><select class="cell-input" onchange="V15.plSource=this.value">'+plSourceOptions()+'</select></div><button class="btn btn-primary" onclick="V15.pullPL()">Pull selected business</button><div class="field"><label>Prior-period income</label><input class="cell-input" type="number" value="'+(P.priorIncome||'')+'" onchange="V15.setPlRoot(\'priorIncome\',this.value)"></div><div class="field"><label>Prior-period expenses</label><input class="cell-input" type="number" value="'+(P.priorExpenses||'')+'" onchange="V15.setPlRoot(\'priorExpenses\',this.value)"></div><div class="field"><label>Difference flag %</label><input class="cell-input" type="number" value="'+N(P.cushionPct)+'" onchange="V15.setPlRoot(\'cushionPct\',this.value)"></div>';input.insertBefore(source,input.children[1]||null);
      $$('.v14-formgrid input[type="date"]',input).forEach(function(el){var label=(el.parentNode.querySelector('label')||{}).textContent||'';var key=/beginning/i.test(label)?'start':/ending/i.test(label)?'end':'prepared';el.dataset.v15Key=key;enhanceDateInput(el);});
      var t=plTotals(),months=plMonths(),monthly=t.net/months,src=N(P.sourceMonthly),delta=src?monthly-src:0,diff=src?delta/Math.abs(src)*100:null,prior=N(P.priorIncome),revChange=prior?(t.inc-prior)/prior*100:null,threshold=Math.max(0,N(P.cushionPct)),risk=t.net<0||t.margin<5?'High':(t.margin<15||t.ratio>75?'Moderate':'Low'),cls=risk==='High'?'bad':risk==='Moderate'?'warn':'';
      var notes=[];notes.push(t.inc>0?'Income lines total and reconcile to the statement total.':'No income amount is entered.');notes.push(t.exp>t.inc?'Expenses exceed income for the covered period.':'Expenses are '+t.ratio.toFixed(1)+'% of income.');if(diff!=null)notes.push('Monthly net is '+Math.abs(diff).toFixed(1)+'% '+(diff>=0?'above':'below')+' the linked qualifying-income figure.');if(revChange!=null)notes.push('Income is '+Math.abs(revChange).toFixed(1)+'% '+(revChange>=0?'above':'below')+' the prior period.');
      var analysis=document.createElement('div');analysis.className='v15-analysis';analysis.innerHTML='<h2>Income analysis</h2><div class="v15-analysis-grid"><div><span>Months covered</span><b>'+months.toFixed(2)+'</b></div><div><span>Average monthly net</span><b>'+money(monthly)+'</b></div><div><span>Expense ratio</span><b>'+t.ratio.toFixed(1)+'%</b></div><div><span>Net margin</span><b>'+t.margin.toFixed(1)+'%</b></div><div><span>Linked qualifying income</span><b>'+money(src)+'/mo</b></div><div><span>Income cushion / shortfall</span><b>'+money(delta)+'/mo</b></div><div><span>Difference</span><b>'+(diff==null?'Not linked':diff.toFixed(1)+'%')+'</b></div><div><span>Assessment</span><b>'+risk+'</b></div></div><div class="v15-flag '+cls+'">'+notes.join(' ')+'</div>'+(diff!=null&&Math.abs(diff)>=threshold?'<div class="v15-flag warn">Difference flag: '+Math.abs(diff).toFixed(1)+'% exceeds the selected '+threshold.toFixed(1)+'% review threshold. Review deposits, unusual expenses, seasonality, and the tax-return calculation.</div>':'')+(P.sourceLabel?'<p><b>Linked source:</b> '+esc(P.sourceLabel)+'. The link is for analysis; statement rows remain manually editable.</p>':'');doc.appendChild(analysis);
    };wrapped.__v15=true;V14.renderPL=wrapped;V13.renderPL=wrapped;}
  V14.renderPL();var head=$('v13PlModal')&&$('v13PlModal').querySelector('.v13-head');if(head&&!head.__v15){head.__v15=true;var print=head.querySelector('button');if(print){print.textContent='Print statement only';print.onclick=function(){V.printNode('v15PlStatement','Profit and Loss Statement');};}}return true;
}

/* Mortgage insurance: show live conventional PMI table and FHA UFMIP/MIP table. */
V.renderMI=function(){var st=suite(),h=$('v13PmiResults');if(!st||!h)return;if(window.V13&&V13.pmiCalc)V13.pmiCalc();var old=$('v15MiLive');if(old)old.remove();var i=st.activeInputs,o=st.outputs,fico=N(i.creditScore),down=N(i.finalDownPaymentPct),tier=fico>=760?'Excellent (760+)':fico>=700?'Good (700-759)':fico>=640?'Fair (640-699)':'Below 640',band=down>=.15?'15% - 20% down':down>=.10?'10% - 15% down':'< 10% down';var pmi=[['Excellent (760+)','.450%','.400%','.300%'],['Good (700-759)','.750%','.500%','.400%'],['Fair (640-699)','1.100%','.750%','.600%'],['Below 640','1.350%','1.000%','.800%']];var mip=[['30','<= $726,200','<= 90%','.500%','11 years'],['30','> $726,200','<= 90%','.700%','11 years'],['30','<= $726,200','90.01% - 95%','.500%','Life of loan'],['30','> $726,200','90.01% - 95%','.700%','Life of loan'],['30','<= $726,200','> 95%','.550%','Life of loan'],['30','> $726,200','> 95%','.750%','Life of loan']];var d=document.createElement('div');d.id='v15MiLive';d.innerHTML='<div class="v15-analysis-grid" style="margin-top:12px"><div><span>Program</span><b>'+esc(i.loanProgram)+'</b></div><div><span>Base loan</span><b>'+money(o.loan.maximumBaseLoan)+'</b></div><div><span>UFMIP</span><b>'+money(o.loan.ufmip)+' @ '+(N(i.ufmipRate)*100).toFixed(3)+'%</b></div><div><span>Monthly '+(o.isFha?'MIP':'PMI')+'</span><b>'+money(o.isFha?o.payment.monthlyFhaMip:o.payment.monthlyPmi)+'</b></div></div><h3>Conventional PMI planning table</h3><table class="v13-table v15-mi-table"><thead><tr><th>Credit tier</th><th>&lt; 10% down</th><th>10% - 15% down</th><th>15% - 20% down</th></tr></thead><tbody>'+pmi.map(function(r){return '<tr class="'+(r[0]===tier?'v15-mi-current':'')+'">'+r.map(function(c){return '<td>'+c+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table><div class="muted small">Current planning band: '+esc(tier)+' / '+esc(band)+'. The manually entered PMI rate continues to control the live scenario.</div><h3>FHA annual MIP planning table</h3><table class="v13-table v15-mi-table"><thead><tr><th>Term</th><th>Base loan</th><th>LTV</th><th>Annual MIP</th><th>Duration</th></tr></thead><tbody>'+mip.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+c+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table><div class="note"><div>UFMIP and annual MIP are separate. The suite uses the selected FHA annual MIP rate and recalculates the monthly payment immediately. Conventional PMI remains an insurer-quoted estimate; the worksheet models borrower-requested removal at 80% LTV and shows the scheduled timing estimate.</div></div>';h.appendChild(d);};
