/* A fuller one-page residential lease layout, populated from the same fields. */
function enhanceLease(){if(!window.V14||!V14.renderLease)return false;if(V14.renderLease.__v15)return true;var old=V14.renderLease;V14.renderLease=function(){old();var h=$('v14LeaseBody'),x=V14.LEASE;if(!h)return;var doc=h.querySelector('.v14-doc');if(!doc)return;doc.id='v15LeaseStatement';doc.className='v14-doc v15-lease';doc.innerHTML='<h1>RESIDENTIAL LEASE AGREEMENT</h1><p>This Residential Lease Agreement is entered into by <b>'+esc(x.landlord)+'</b> (Landlord) and <b>'+esc(x.tenant)+'</b> (Tenant).</p><div class="clause-grid"><div><h2>1. PREMISES</h2><p>Landlord rents to Tenant the residential premises at <b>'+esc(x.property)+'</b>, together with the fixtures and improvements serving the premises.</p><h2>2. TERM</h2><p>The tenancy begins <b>'+esc(x.start)+'</b> and ends <b>'+esc(x.end)+'</b>, unless ended earlier under this agreement or applicable law.</p><h2>3. RENT</h2><p>Monthly rent is <b>'+money(x.rent)+'</b>, due on day <b>'+esc(x.dueDay)+'</b> of each month at the place or by the method designated by Landlord. Any stated late charge is <b>'+money(x.lateFee)+'</b>, subject to applicable law.</p><h2>4. SECURITY DEPOSIT</h2><p>The security deposit is <b>'+money(x.deposit)+'</b>. It may be applied only as permitted by law and is not advance rent.</p><h2>5. OCCUPANCY AND USE</h2><p>The premises will be used only as a private residence by: '+esc(x.occupants)+'. Tenant may not assign or sublet without required written consent.</p></div><div><h2>6. UTILITIES AND SERVICES</h2><p>'+esc(x.utilities||'Utilities and services are allocated as separately agreed by the parties.')+'</p><h2>7. CARE, REPAIRS, AND ALTERATIONS</h2><p>Tenant will keep the premises reasonably clean, promptly report unsafe or damaged conditions, and obtain written consent before material alterations. Each party remains responsible for duties imposed by law.</p><h2>8. ACCESS</h2><p>Landlord may enter for inspection, repairs, services, or showing the premises with notice required by law, and may enter without advance notice in an emergency.</p><h2>9. RULES, DEFAULT, AND LAW</h2><p>Tenant will comply with lawful rules and avoid nuisance or illegal activity. Remedies, notices, fees, and termination are governed by applicable state and local law.</p><h2>10. ADDITIONAL TERMS</h2><p>'+esc(x.terms||'None.')+'</p><h2>11. ENTIRE AGREEMENT</h2><p>This writing and any signed addenda are the entire agreement. Changes must be in writing and signed by the parties.</p></div></div><div class="sign-grid"><div class="sig">Landlord signature / Date</div><div class="sig">Tenant signature / Date</div><div class="sig">Landlord printed name</div><div class="sig">Tenant printed name</div></div>';};V14.renderLease();var head=$('v14LeaseModal')&&$('v14LeaseModal').querySelector('.v13-head');if(head&&!head.__v15){head.__v15=true;var b=head.querySelector('button');if(b)b.onclick=function(){V.printNode('v15LeaseStatement','Residential Lease Agreement');};}return true;}

/* Contractor rows can be allocated on explicit request; the selected split is visible. */
V.allocateLabor=function(){if(!window.V14)return;var rows=V14.CON.rows||[],has=rows.some(function(r){return N(r.material)+N(r.labor)>0;});if(!has)return say('Enter line totals first','Enter either labor or materials on at least one scope row, then allocate.','warn');var pct=60+Math.random()*10;rows.forEach(function(r){var total=N(r.material)+N(r.labor);r.labor=Math.round(total*pct)/100;r.material=Math.round((total-r.labor)*100)/100;});V14.CON.laborAllocationPct=pct;V14.renderContractor();say('Labor and material split applied',pct.toFixed(1)+'% labor / '+(100-pct).toFixed(1)+'% materials. The displayed amounts remain editable.');};
function enhanceContractor(){if(!window.V14||!V14.renderContractor)return false;if(!V14.renderContractor.__v15){var old=V14.renderContractor;var wrapped=function(){old();var h=$('v14ConBody');if(!h)return;var edit=h.querySelector('.v14-doc-inputs'),doc=h.querySelector('.v14-doc');if(doc)doc.id='v15ContractorStatement';if(edit&&!edit.querySelector('.v15-labor-rule')){var mat=0,lab=0;(V14.CON.rows||[]).forEach(function(r){mat+=N(r.material);lab+=N(r.labor);});var share=mat+lab?lab/(mat+lab)*100:0,d=document.createElement('div');d.className='v15-labor-rule';d.innerHTML='<div class="v14-bar"><button class="btn btn-primary" onclick="V15.allocateLabor()">Allocate 60-70% labor</button><b>'+(V14.CON.laborAllocationPct?V14.CON.laborAllocationPct.toFixed(1)+'% labor / '+(100-V14.CON.laborAllocationPct).toFixed(1)+'% materials':'No automatic split applied')+'</b></div><div class="muted small">Current base-cost split: '+share.toFixed(1)+'% labor / '+(100-share).toFixed(1)+'% materials. Allocation runs only when the button is clicked; every row stays editable.</div>'+(mat+lab&& (share<60||share>70)?'<div class="v15-flag warn">Cost check: labor is outside the 60-70% planning range.</div>':'');var section=edit.querySelector('.v14-section');edit.insertBefore(d,section||edit.firstChild);}};wrapped.__v15=true;V14.renderContractor=wrapped;}V14.renderContractor();return true;}

