V.amortization=function(principal,annualRate,years){var P=Number(principal)||0,r=(Number(annualRate)||0)/12,n=Math.max(1,Math.round((Number(years)||30)*12)),pmt=r?P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1):P/n,bal=P,rows=[];for(var m=1;m<=n;m++){var interest=bal*r,principalPaid=Math.min(bal,pmt-interest);bal=Math.max(0,bal-principalPaid);rows.push({month:m,payment:pmt,principal:principalPaid,interest:interest,balance:bal});}return{payment:pmt,rows:rows};};
V.openAmortization=function(){var store=st();if(!store)return;var i=store.activeInputs,o=store.outputs,a=V.amortization(o.loan.totalLoan,i.interestRate,i.termYears),annual=[];for(var y=0;y<Math.ceil(a.rows.length/12);y++){var group=a.rows.slice(y*12,y*12+12),pr=group.reduce(function(s,x){return s+x.principal;},0),it=group.reduce(function(s,x){return s+x.interest;},0);annual.push('<tr><td>Year '+(y+1)+'</td><td>'+money(group.reduce(function(s,x){return s+x.payment;},0))+'</td><td>'+money(pr)+'</td><td>'+money(it)+'</td><td>'+money(group[group.length-1].balance)+'</td></tr>');}var bg=document.createElement('div');bg.className='modal-bg no-print';bg.innerHTML='<div class="modal"><header><h3>Amortization schedule</h3><span style="flex:1"></span><button class="btn ghost small">Close</button></header><div class="content"><div class="v20-kpis"><div><span>Loan amount</span><b>'+money(o.loan.totalLoan)+'</b></div><div><span>Rate</span><b>'+(Number(i.interestRate)*100).toFixed(3)+'%</b></div><div><span>Term</span><b>'+i.termYears+' years</b></div><div><span>Monthly P&amp;I</span><b>'+money(a.payment)+'</b></div></div><div class="v20-amort-table"><table><thead><tr><th>Period</th><th>Payments</th><th>Principal</th><th>Interest</th><th>Ending balance</th></tr></thead><tbody>'+annual.join('')+'</tbody></table></div></div></div>';bg.querySelector('button').onclick=function(){bg.remove();};bg.onclick=function(e){if(e.target===bg)bg.remove();};($('suite-root')||document.body).appendChild(bg);};

