function summaryAmortization(){var s=store(),body=$('screen-body');if(!s||s.snapshot.mode!=='summary'||!body||!window.V20)return;var old=$('v21SummaryAmort');if(old)old.remove();var i=s.activeInputs,o=s.outputs,a=V20.amortization(o.loan.totalLoan,i.interestRate,i.termYears),first=a.rows.slice(0,12),totalInterest=a.rows.reduce(function(t,r){return t+r.interest;},0),d=document.createElement('div');d.id='v21SummaryAmort';d.className='card v21-summary-amort';d.innerHTML='<h3>Amortization schedule</h3><div class="body"><div class="v20-kpis"><div><span>Loan amount</span><b>'+money(o.loan.totalLoan)+'</b></div><div><span>Monthly P&amp;I</span><b>'+money(a.payment)+'</b></div><div><span>Total scheduled interest</span><b>'+money(totalInterest)+'</b></div><div><span>Term</span><b>'+N(i.termYears)+' years</b></div></div><div class="table-wrap"><table><thead><tr><th>Month</th><th>Payment</th><th>Principal</th><th>Interest</th><th>Balance</th></tr></thead><tbody>'+first.map(function(r){return'<tr><td>'+r.month+'</td><td>'+money(r.payment)+'</td><td>'+money(r.principal)+'</td><td>'+money(r.interest)+'</td><td>'+money(r.balance)+'</td></tr>';}).join('')+'</tbody></table></div><div class="v20-quick"><button class="btn small" onclick="V20.openAmortization()">Open full annual schedule</button></div></div>';var summary=body.querySelector('[data-section="summary"]'),anchor=summary||$('v15SummaryProperty');if(anchor&&anchor.nextSibling)body.insertBefore(d,anchor.nextSibling);else body.appendChild(d);}

