  var html = card('Monthly payment', usd(p.totalMonthlyPayment,2), 'setup', 'P&I, MI, taxes and insurance', 'card')
    + card('Cash to close', usd(cash.cashToClose,2), 'closing', 'After credits and deposits', 'cash')
